sys_script_include.script:
var ContrastAppListIntegrationJsonSAST = Class.create();
ContrastAppListIntegrationJsonSAST.prototype = Object.extendsObject(sn_vul.ApplicationVulnerabilityIntegrationBase, {

    retrieveData: function() {
        var util = new x_ntsi_contrast_ap.ContrastUtilBase();
        var arr = [];
        var page_number = 0;
        var rtn_count = true;
        while (rtn_count) {
            var resp = util.triggerAPISAST(this.IMPLEMENTATION, page_number);
            if (resp.getStatusCode() != 200) {
                gs.error("API Failed with status code: " + resp.getStatusCode());
                break;
            }

            var body = resp.getBody();
            var contentjson = JSON.parse(body);
            if (!body || contentjson.numberOfElements == 0) break;

            try {

                var responseContent = contentjson.content;
                var appURL = util.getApiURLDetails();

                for (var a in responseContent) {
                    var pageNum = 0,
                        rtn = true;

                    while (rtn) {
                        var vulresp = util.getSASTVulnerabilities(this.IMPLEMENTATION, responseContent[a].id, pageNum);
                        var vulBody = vulresp.getBody();
                        if (!vulBody || vulBody.indexOf('numberOfElements') == -1) break;

                        var vul = JSON.parse(vulBody);
                        if (vul.numberOfElements == 0) break;

                        var trace = vul.content;
                        for (var a1 in trace) {
                            var obj = trace[a1];
                            delete obj.locations;
                            delete obj.codeFlows;
                            obj.source_link = "https://" + appURL + "/Contrast/api/sast/organizations/" +
                                trace[a1].organizationId + "/projects/" + trace[a1].projectId +
                                "/results/" + trace[a1].id;
                            obj.name = responseContent[a].name;
                            if (trace[a1].status != "REMEDIATED") arr.push(obj);
                        }
                        pageNum++;
                    }
                }
            } catch (e) {
                gs.error("Failed to parse JSON: " + e.message);
            }
            page_number++;
        }

        var attachmentGr = new GlideSysAttachment();
        var fileName = this.integrationGr.name + "_" + new GlideDateTime().toString() + ".json";
        var sysId = attachmentGr.write(this.integrationGr, fileName, "json", JSON.stringify({
            content: arr
        }));

        return {
            contents: sysId,
            contentType: "sys_attachment",
            extension: "json"
        };
    },

    shouldRetry: function() {
        return true;
    },

    type: 'ContrastAppListIntegrationJsonSAST'
});
